        description: "Quando o rastejador de enxame é reduzido a 0 PV, suas criaturas constituintes desmoronam, espalhando-se no chão sob seu espaço e em cada espaço adjacente. Se mesmo uma das criaturas escapa, o rastejador de enxame pode eventualmente se reconstituir em 1d10 dias (potencialmente mais tempo em áreas com poucos invertebrados). Os invertebrados dispersos devem ser destruídos em 1 rodada para destruir o rastejador de enxame permanentemente. Os invertebrados têm um pool coletivo de 55 PV e a mesma CA, salvaguardas, imunidades, resistências e vulnerabilidades que o rastejador de enxame. Os invertebrados não podem tomar ações, mas escapam automaticamente quando a rodada termina. A critério do Mestre, meios inteligentes de prender ou eliminar as criaturas podem ser suficientes para destruir o rastejador de enxame.",
