        description: "Os mil ladrões desmoronam em um enxame sem forma de suas criaturas constituintes. Abandonam todos os objetos segurados, vestidos ou carregados, exceto até 3 de Carga.\nNesta forma, os mil ladrões não podem usar ações de ataque nem conjurar magias, mas podem se mover por áreas pequenas o suficiente para suas criaturas constituintes sem precisar Apertar-se. Podem usar a mesma ação para coalescer de sua forma de enxame de volta à forma normal.\nEnquanto o enxame se move, os mil ladrões carregam esses objetos se podem passar pelos espaços que o enxame atravessa. Os mil ladrões vestem automaticamente qualquer objeto que desejam ao se reconstituir. Se os mil ladrões estão Escondidos, Fuga do Enxame não revela sua localização.",
