        description: "O eseneth tenta arrancar a alma da criatura exigida. O eseneth faz um teste de Atletismo contra a CD de Fortitude do alvo.\nSucesso crítico O eseneth agarra a alma do alvo. O corpo é solto e fica Paralisado por 2 rodadas. Quando o corpo deixa de estar paralisado, sua alma retorna instantaneamente e o alvo desperta. A alma — agarrada pelo eseneth — é incorpórea, é Invisível, tem Deslocamento de voo igual ao Deslocamento da criatura e, de resto, tem as mesmas estatísticas. Não pode atacar, conjurar magias nem tentar testes de perícia que exijam corpo físico, exceto testes para Escapar (CD 38), e deve sempre manter linha de efeito com seu corpo.\nSucesso Como sucesso crítico, mas a paralisia termina após 1 rodada.\nFalha O alvo permanece Agarrado ou Imobilizado, mas sua alma permanece no corpo.\nFalha crítica O alvo deixa de estar Agarrado ou Imobilizado.",
