        name: "Terror Interminável",
        originalName: "Unending Terror",
        actionType: "passive",
        description: "Escapar do medo perto de um fasmadæmon não é tarefa simples. Criaturas não reduzem automaticamente sua condição Amedrontada enquanto estiverem na aura Presença Aterradora do fasmadæmon. Em vez disso, devem tentar uma salvaguarda de Vontade no fim do turno contra a CD do efeito que causou a condição. Em sucesso, a condição Amedrontada da criatura é reduzida em 1.",
