        description: "18 m. A entropia de um nasurgeth fica ainda mais forte debaixo d'água. Toda a água dentro da aura fica completamente escura (como escuridão de 4º círculo). Luz mágica com nível de neutralização de 4º círculo ou inferior, junto com truques de luz mágica, são suprimidos. Uma criatura viva que entrar ou iniciar seu turno na aura sofre 4d6 de vazio de dano, e a criatura também sofre 2d10 de dano de frio adicional se estiver na água (salvaguarda de Fortitude CD 39). Se falhar, ela também fica Enfraquecida 1 por 1 minuto e é puxada 3 m em direção ao nasurgeth.",
