        originalName: "Plantsense 60 feet",
        actionType: "passive",
        description: "Um homem verde pode sentir a força vital por meio de plantas. Isso lhe permite observar a essência vital de uma criatura viva ou morta-viva a até 18 m do homem verde, mas ele também pode usar esse sentido preciso para observar qualquer criatura viva ou morta-viva a até 18 m de qualquer matéria vegetal a até 36 m do homem verde. Isso permite ao homem verde enxergar seres vivos através de matéria vegetal sólida, bem como enxergar através de outras barreiras se houver plantas do outro lado.",
