        name: "Absorver Magia",
        originalName: "Absorb Magic",
        actionType: "one",
        description: "As vinhas do homem verde drenam magia e a transformam em essência vital para o homem verde. Com um Golpe de vinha bem-sucedido, o homem verde tenta neutralizar uma magia ativa no alvo (tipicamente uma que o incomoda, ou determinada aleatoriamente se ele não estiver ciente de efeitos específicos), com nível de neutralização 10 e modificador +38.\nSe o efeito for neutralizado, o homem verde ganha 30 PV temporários que duram 10 minutos.",
